pragma solidity ^0.8.9;

import {IDolomiteMargin} from "../interfaces/dolomite/IDolomiteMargin.sol";
import {DolomiteMarginMath} from "./DolomiteMarginMath.sol";

/**
 * @title   InterestIndexLib
 * @author  Dolomite
 *
 * @notice  Library contract that checks a user's balance after transaction to be non-negative
 */
library InterestIndexLib {
    using DolomiteMarginMath for uint256;

    // ============ Constants ============

    bytes32 private constant _FILE = "InterestIndexLib";
    uint256 private constant _BASE = 1e18;

    // ============ Functions ============

    /**
     *  Converts the scaled Par value to an actual Wei value
     */
    function parToWei(
        IDolomiteMargin dolomiteMargin,
        uint256 _marketId,
        IDolomiteMargin.Par memory _amountPar
    ) internal view returns (IDolomiteMargin.Wei memory) {
        IDolomiteMargin.InterestIndex memory index = dolomiteMargin
            .getMarketCurrentIndex(_marketId);
        if (_amountPar.sign) {
            return
                IDolomiteMargin.Wei({
                    sign: true,
                    value: uint256(_amountPar.value).getPartialRoundHalfUp(
                        index.supply,
                        _BASE
                    )
                });
        } else {
            return
                IDolomiteMargin.Wei({
                    sign: false,
                    value: uint256(_amountPar.value)
                        .getPartialRoundHalfUp(index.borrow, _BASE)
                        .to128()
                });
        }
    }

    /**
     *  Converts an actual Wei value to a scaled Par value
     */
    function weiToPar(
        IDolomiteMargin dolomiteMargin,
        uint256 _marketId,
        IDolomiteMargin.Wei memory _amountWei
    ) internal view returns (IDolomiteMargin.Par memory) {
        IDolomiteMargin.InterestIndex memory index = dolomiteMargin
            .getMarketCurrentIndex(_marketId);
        if (_amountWei.sign) {
            return
                IDolomiteMargin.Par({
                    sign: true,
                    value: _amountWei
                        .value
                        .getPartialRoundHalfUp(_BASE, index.supply)
                        .to128()
                });
        } else {
            return
                IDolomiteMargin.Par({
                    sign: false,
                    value: _amountWei
                        .value
                        .getPartialRoundHalfUp(_BASE, index.borrow)
                        .to128()
                });
        }
    }

    /*
     * Convert a principal amount to a token amount given an index.
     */
    function parToWei(
        IDolomiteMargin.Par memory input,
        IDolomiteMargin.InterestIndex memory index
    ) internal pure returns (IDolomiteMargin.Wei memory) {
        uint256 inputValue = uint256(input.value);
        if (input.sign) {
            return
                IDolomiteMargin.Wei({
                    sign: true,
                    value: inputValue.getPartialRoundHalfUp(index.supply, _BASE)
                });
        } else {
            return
                IDolomiteMargin.Wei({
                    sign: false,
                    value: inputValue.getPartialRoundHalfUp(index.borrow, _BASE)
                });
        }
    }

    /*
     * Convert a token amount to a principal amount given an index.
     */
    function weiToPar(
        IDolomiteMargin.Wei memory input,
        IDolomiteMargin.InterestIndex memory index
    ) internal pure returns (IDolomiteMargin.Par memory) {
        if (input.sign) {
            return
                IDolomiteMargin.Par({
                    sign: true,
                    value: input
                        .value
                        .getPartialRoundHalfUp(_BASE, index.supply)
                        .to128()
                });
        } else {
            return
                IDolomiteMargin.Par({
                    sign: false,
                    value: input
                        .value
                        .getPartialRoundHalfUp(_BASE, index.borrow)
                        .to128()
                });
        }
    }
}

